<?php $title='Register | ScholarHub'; require 'includes/header.php'; require 'config/db.php'; $err='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$p=$_POST['password']??'';if($n===''||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($p)<6)$err='Use a valid name, email and password of at least 6 characters.';else{try{$st=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'student')");$st->execute([$n,$e,password_hash($p,PASSWORD_DEFAULT)]);header('Location: login.php?registered=1');exit;}catch(PDOException $x){$err='Email already exists.';}}} ?><div class="container py-5"><div class="row justify-content-center"><div class="col-md-6"><div class="card p-4"><h2>Create account</h2><?php if($err): ?><div class="alert alert-danger"><?=e($err)?></div><?php endif; ?><form method="post"><input class="form-control mb-3" name="name" placeholder="Full name" required><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" type="password" name="password" placeholder="Password (6+ characters)" required><button class="btn btn-primary w-100">Register</button></form></div></div></div></div><?php require 'includes/footer.php'; ?>
